            "knowledge_spans": [
                {
                    "text": "信创产业是数字经济、信息安全发展的基础，也是“新基建”的重要内容，其核心在于通过行业应用拉动构建国产化信息技术软硬件底层架构体系和全周期生态体系，解决核心技术关键环节“卡脖子”问题。",
                    "role": "信创产业定义与核心",
                    "stability": "high"
                },
                {
                    "text": "以产业链的角度进行区分，信创产业可以被分为五个大类，分别是基础硬件、基础软件、云计算、应用软件、以及信息安全。",
                    "role": "信创产业链分类",
                    "stability": "high"
                },
                {
                    "text": "真正的技术落差在于基础硬件、基础软件、应用软件：从全球与中国市场的技术成熟度方面来看，无论是云计算，还是信息安全层面，我国与世界技术成熟度水平的差距都较小，而在基础硬件、基础软件、应用软件方面的差距较大。",
                    "role": "信创技术差距分析",
                    "stability": "medium"
                }
            ],
            "event_residue": null,
            "drop_target": null
        },
        {
